begin;
select plan(36);
select has_column('public','together_shared_plans','window_starts_at','Plans preserve the beginning of a fuzzy time window');
select has_column('public','together_shared_plans','window_ends_at','Plans preserve the end of a fuzzy time window');
select has_column('public','together_shared_plans','time_precision','Plans preserve human time precision');
select has_column('public','together_shared_plans','world_timezone','Plans preserve canonical world-local time');
select has_column('public','together_shared_plans','user_timezone','Plans preserve viewer timezone context');
select has_column('public','together_shared_plans','original_time_expression','Plans remember the user time phrase');
select has_column('public','together_shared_plans','participation_mode','Commitments declare live, flexible, or ambient participation');
select has_column('public','together_shared_plans','grace_minutes','Live commitments have an explicit grace duration');
select has_column('public','together_shared_plans','grace_ends_at','Live commitments have a canonical grace deadline');
select has_column('public','together_shared_plans','missed_at','Missed commitments retain when the miss was settled');
select has_column('public','together_shared_plans','miss_reason','Miss attribution is canonical');
select has_column('public','together_shared_plans','companion_state','Companions can canonically be expected, late, absent, or cancelled');
select has_column('public','together_shared_plans','companion_eta_at','Late companion ETA is canonical');
select has_column('public','together_shared_plans','companion_reason','Companion disruption retains its reason');
select has_table('public','together_plan_attendance','Commitment attendance is explicit');
select has_table('public','together_missed_plan_resolutions','Missed commitments have repair state');
select has_column('public','together_date_sessions','shared_plan_id','Dates specialize SharedPlan timing');
select has_column('public','together_trips','shared_plan_id','Trips specialize SharedPlan timing');
select has_column('public','together_date_templates','metadata','Date templates can declare canonical duration metadata');
select ok((select relrowsecurity from pg_class where oid='public.together_plan_attendance'::regclass),'Attendance state uses RLS');
select ok((select relrowsecurity from pg_class where oid='public.together_missed_plan_resolutions'::regclass),'Miss repair state uses RLS');
select trigger_is('public','together_conversation_actions','together_conversation_action_time_precision','public','kivelle_normalize_conversation_plan_time','Chat proposals normalize human timing before persistence');
select trigger_is('public','together_date_sessions','together_date_session_commitment_sync','public','kivelle_sync_date_commitment','Date scheduling mirrors into SharedPlan');
select trigger_is('public','together_trips','together_trip_commitment_sync','public','kivelle_sync_trip_commitment','Trip scheduling mirrors into SharedPlan');
select trigger_is('public','together_shared_plans','together_shared_plan_life_beats','public','kivelle_sync_commitment_life_beats','Commitments affect the lived companion timeline');
select trigger_is('public','together_plan_attendance','together_plan_attendance_cleanup','public','kivelle_commitment_attendance_cleanup','Arrival ends the waiting state');
select trigger_is('public','together_messages','together_message_missed_commitment_repair','public','kivelle_capture_missed_commitment_explanation','Chat can canonically explain and repair a missed commitment');
select trigger_is('public','together_shared_plans','together_shared_plan_specialization_sync','public','kivelle_sync_commitment_specialization','SharedPlan remains authoritative for Date and Trip timing');
select trigger_is('public','together_shared_plans','together_shared_plan_missed_aftermath','public','kivelle_close_missed_commitment','A missed commitment creates canonical aftermath');
select trigger_is('public','together_life_events','together_life_event_commitment_impact','public','kivelle_apply_life_event_commitment_impact','Authored life events can make a companion late or absent');
select ok(to_regprocedure('public.kivelle_progress_shared_plans(uuid,uuid,timestamptz)') is not null,'Attendance-aware plan progression is installed');
select ok(to_regprocedure('public.kivelle_mark_character_commitment_exception(uuid,text,text,timestamptz)') is not null,'Canonical companion late/absent hook is installed');
select ok(to_regprocedure('public.kivelle_mark_commitment_failure(uuid,text,text,timestamptz)') is not null,'Technical commitment failure attribution is installed');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_shared_plans'::regclass and conname='together_shared_plans_status_check' and pg_get_constraintdef(oid) like '%missed%'),'SharedPlan status permits missed commitments');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_shared_plans'::regclass and conname='together_shared_plans_canonical_timing_check'),'Proposal-aware timing constraint is installed');
select ok(exists(select 1 from pg_constraint where conrelid='public.together_conversation_events'::regclass and conname='together_conversation_events_event_type_check' and pg_get_constraintdef(oid) like '%plan_missed%' and pg_get_constraintdef(oid) like '%plan_repaired%'),'Conversation receipts include miss and repair events');
select * from finish();
rollback;
